A Hausdorff topological space $\cM$ is said to be an \emph{$n$-dimensional manifold} if it has a countable basis and for each $p \in \cM$ there exist a neighborhood $U$ of $p$, an open subset $\hat U \subset \R^n$ and a map $\varphi: U \to \hat U$ such that $\varphi$ is a homeomorphism. The pair $(U, \varphi)$ is called a \emph{chart}.


\begin{definition}  %
    A \emph{tangent vector} $\xi_p:\cD(\cM)\to\R$ to a manifold $\cM$ at a point $p$ is a linear operator such that for every $f \in \cD(\cM)$, %
        $\xi_p f = \dot\gamma(0) f:= \left.\frac{\dd(f(\gamma(t)))}{\dd t}\right|_{t=0}$,
    where $\gamma: (-1, 1) \to \cM$ is a smooth curve on $\cM$ with $\gamma(0)=p$.
\end{definition}

The \emph{tangent space} $T_p\cM$ is the space containing all tangent vectors at $p$, which is an $n$-dimensional $\R$-linear space. 
A \emph{Riemannian metric} $\langle\cdot,\cdot\rangle_p$ gives an inner product on $T_p\cM$, which smoothly depends on~$p$.\footnote{The subscript $p$ in $\inner{\cdot}{\cdot}_p$ is usually omitted for simplicity.}
Moreover, a Riemannian metric gives a metric on $\cM$ and the gradient of functions defined on $\cM$.
Below we assume that $\cM$ is equipped with a Riemannian metric.
\begin{definition} %
	Given $p,q\in\cM$, the \emph{distance between $p$ and $q$} is defined as 
	\begin{equation*}
	d(p,q) = \inf \left\{ \ell(\gamma)  :  \ell(\gamma) := \int_0^1 \sqrt{\inner{\dot \gamma(t)}{\dot\gamma(t)}} \dd t \right\},
	\end{equation*}
	where $\inf$ is taken over all piecewise smooth curves $\gamma:[0,1]\to\cM$  with $\gamma(0)=p$ and $\gamma(1)=q$.
\end{definition}

\begin{definition}
    Let $f: \cM \to \cN$ be a smooth map between smooth manifolds $\cM, \cN$, the \emph{differential of $f$ at $p\in\cM$}, denoted by $\dd f|_p$, is a map from $T_p\cM$ to $T_{f(p)}\cN$ such that $(\dd f|_p\eta) g:= \eta(g \circ f)$ for all $g \in \cD(\cN)$ and $\eta \in T_p\cM$.
\end{definition}

\begin{definition}%
	\label{def:riemannian-gradient}
	Let $f:\cM\to\R$ be a smooth function 
	and $p\in\cM$, the \emph{gradient} of $f$ at $p$ is defined as the unique tangent vector $\grad f(p)\in T_p\cM$ that satisfies 
		 $$\xi_p f = \inner{\xi_p}{\grad f(p)},\ \forall\xi_p \in T_p\cM.$$
\end{definition}

Suppose $f: \cM \to \R$ is a locally Lipschitz function\footnote{We say a function $f$ on a manifold is locally Lipschitz if $f \circ \varphi^{-1}$ is locally Lipschitz in $U$ for every chart $(U, \varphi)$.} on a manifold $\cM$ and $(U, \varphi)$ is a chart containing $p \in \cM$. 
From ~\cite{azagra2005nonsmooth,dirr2007nonsmooth,hosseini2011generalized}, the \emph{Clarke generalized directional derivative}  of $f$ at $p$, denoted by $f^\circ(p; v)$, is defined by
\[ f^\circ(p; v) := \limsup_{y \to p, t \downarrow 0} \frac{\hat f(\varphi(y) + t \dd\varphi|_pv) - \hat f(\varphi(y))}{t}, \]
where $\hat f := f \circ \varphi^{-1}$ and $\dd\varphi|_p$ is the differential of $\varphi$ at $p$. The \emph{Clarke subgradient} is 
$$\partial f(p) := \{  \xi \in T_p\cM : \inner{\xi}{v} \leq f^\circ (p; v),\ \forall v \in T_p \cM \}.$$


\begin{equation}
	\label{eqn:original-problem}
	\begin{aligned}
		\min_{x}\  &\{f(x) + \psi(h_1(x)) \}, \quad 
		\mathrm{s.t.}\  x \in \cM,\ h_2(x) \leq 0.
	\end{aligned}
\end{equation}

\begin{assumption}
	$\cM$ is a complete smooth Riemannian manifold.
\end{assumption}

\begin{assumption}
	$f : \cM \to \R$, $h_1: \cM \to \R^m$, $h_2: \cM \to \R^{q}$ are continuously differentiable, and~$\psi: \R^m \to \R$ is a convex function.
	$f(x) + \psi(y)$ is bounded below for $(x, y) \in \cM \times \R^m$.
\end{assumption}

\begin{equation}
	\label{eqn:reformulated-problem}
	\begin{aligned}
		\min_{x, y, z}\  &\{f(x) + \psi(y) \}, \quad
		\mathrm{s.t.}\  x \in \cM, \
		 y = h_1(x), \
		 z = h_2(x),\ z \leq 0.
	\end{aligned}
\end{equation}

The augmented Lagrangian function $L_\sigma: \cM \times \R^m \times \R_-^q \times \R^m \times \R^q \to \R$ of \eqref{eqn:reformulated-problem} is given by
\begin{equation}
	\begin{aligned} 
\peq	L_\sigma(x, y, z, \lambda, \gamma)  
= f(x) + \psi(y) 
+ \frac{\sigma}{2} \norm{h_1(x) - y + \frac{\lambda}{\sigma}}^2_2 
+ \frac{\sigma}{2}\norm{h_2(x) - z + \frac{\gamma}{\sigma}}_2^2 
- \frac{\norm{\lambda}_2^2 + \norm{\gamma}_2^2}{2\sigma}.
	\end{aligned}
	\label{eqn:L_sigma}
\end{equation}

where $\psi^\sigma$, $\delta_{\R^q_-}^\sigma$ are the \emph{Moreau-Yosida regularization} of $\psi$, $\delta_{\R^q_-}$, respectively. 
More specifically, it holds that
\begin{align}
    \psi^\sigma(x) &:= \min_{y \in \R^m}  \left \{ \psi(y)  
    + \frac{\sigma}{2} \norm{x - y}^2_2 \right \}, \label{prob:y}\\
    \delta_{\R_-^q}^\sigma(x) &:= \min_{z \in \R^q} \left \{ \delta_{\R_-^q}(z) + \frac{\sigma}{2}\norm{x - z}_2^2 \right \}, \label{prob:z}
\end{align}

where $\delta_{\R_-^q}$ is the indicator function of $\R_-^q$. 


\begin{alg}[An augmented Lagrangian method for solving \eqref{eqn:reformulated-problem}]
	\label{alg:alm-outer}
	Choose initial values $x_0 \in \cM$, $\gamma_0 \in \R^{q}_+$, $\lambda_0 \in \R^m$, $\sigma_0 > 0$, $\alpha, \tau \in (0, 1)$, $\rho > 1$ 
	and a sequence $\{ \varepsilon_k \} \subseteq \R_+$ converging to $0$.
	Let $y_0 = \prox_{\psi/\sigma_0} ( h_1(x_0) + \lambda_0 / \sigma_0)$, $z_0 = \Pi_{\R_-^q} ( h_2(x_0) + \gamma_0 / \sigma_0)$, where $\Pi_{\R_-^q}$ is the projection onto $\R_-^q$. %
	Choose a feasible point $x_\feas$ and a constant $\Phi$ such that
	\begin{equation}
		\label{eqn:initial-maximal}
		\Phi \geq \max\{  f(x_\feas) + \psi(h_1(x_\feas)),\ L_{\sigma_0}(x_0, y_0, z_0, \lambda_0, \gamma_0)  \}.
	\end{equation}
	Our algorithm repeats the following steps for $k = 1, 2, \dots$

    \begin{enumerate}[label=(\roman*)]
	\item
	Find $x_k\in\cM$ such that
	\begin{equation}
		\label{eqn:subproblem-stopping-rule}
		\norm{\grad L_k (x_k)} < \varepsilon_k, \quad L_k(x_k) \leq \Phi,
	\end{equation}
	where 
	\begin{equation}
	L_k(x) := f(x) 
	+ \psi^{\sigma_k} \left ( h_1(x) + \frac{\lambda_k}{\sigma_k}  \right )
	+ \delta_{\R_-^q}^{\sigma_k} \left ( h_2(x) + \frac{\gamma_k}{\sigma_k}  \right ).
	\label{eqn:Lk}
	\end{equation}
	\item Update $y$ and $z$ using
    \begin{align}
        \label{eqn:subproblem-y}
        y_k &= \prox_{\psi/\sigma_k}\left ( h_1(x_k) + \frac{\lambda_k}{\sigma_k}  \right ),\\
        \label{eqn:subproblem-z}
        z_k &= \Pi_{\R_-^q} \left ( h_2(x_k) +  \frac{\gamma_k}{ \sigma_k} \right).
    \end{align}

	\item %
	Update the multipliers:
    \[ \begin{aligned}
        \lambda_{k+1} &= \lambda_k + \sigma_k (h_1(x_k) - y_k), \quad 
        \gamma_{k+1} = \gamma_k +\sigma_k (h_2(x_k) - z_k).
    \end{aligned} \]

	\item
	Let 
        $     \delta_k = \max\left\{ \norm{h_1(x_k) - y_k}_2,\ \norm{h_2(x_k)-z_k}_2\right\}.
        $ %

		 If $\delta_k \leq \tau \delta_{k-1}$, then $\sigma_{k+1} = \sigma_k$.
		 Otherwise, set
         \begin{equation}
            \label{eqn:alm-update-penalty}
			\sigma_{k+1} = \max \left \{ \rho\sigma_k,\ \norm{\lambda_{k+1}}_2^{1+\alpha},\ \norm{\gamma_{k+1}}_2^{1+\alpha} \right \}. 
		 \end{equation}
	\end{enumerate}
\end{alg}

Consider the problem \eqref{eqn:original-problem}, we define the \emph{active set} of a feasible point $x$ to be
$\cA(x) := \{ i \in [q] : [h_2(x)]_i = 0 \}$.


\begin{definition}[LICQ]
	\label{def:LICQ}
	We say that a feasible point $x \in \cM$ of \eqref{eqn:original-problem} satisfies the \emph{linear independence constraint qualification} (LICQ) if
    $\{ \grad\, [h_2(x)]_i : i \in \cA(x) \}$ are linearly independent in $T_x\cM$.
\end{definition}

\begin{definition}[CPLD]
	\label{def:CPLD}
	Let $x \in \cM$ be a feasible point of \eqref{eqn:original-problem} and define
    $S(x) := \{ \grad\, [h_2(x)]_i : i \in \cA(x) \}$.
	We say that $x$ satisfies the \emph{constant positive linear dependence constraint qualification} (CPLD) 
	if for each subset $S_0(x) \subseteq S(x)$ whose elements are linearly dependent with non-negative coefficients, $S_0$ remains linearly dependent in a neighborhood of $x$. 
\end{definition}

The Lagrangian of the equivalent problem \eqref{eqn:reformulated-problem} is
\[ \tilde \cL(x, y, z, \lambda, \gamma) = f(x) + \psi(y) + \lambda^\trans(h_1(x) - y) + \gamma^\trans(h_2(x) - z). \]


    \begin{subequations}
        \label{eqn:reformulated-kkt}
        \begin{align}
			 y = h_1(x),\ z = h_2(x), \label{eqn:reformulated-kkt-feas} \\
			 z \in \R^q_-,\ 
            \gamma \in \R^q_+,\ \gamma^\trans z = 0, \label{eqn:reformulated-kkt-z} \\
            0 \in \partial_y \tilde \cL(x, y, z, \lambda, \gamma), \label{eqn:reformulated-kkt-y} \\
            \mathrm{grad}_x\, \tilde \cL(x, y, z, \lambda, \gamma) = 0. \label{eqn:reformulated-kkt-x}
        \end{align}
	\end{subequations}

