\begin{theorem}
    \label{thm:kkt}
    Suppose there exist $K \subseteq \N$ and $(x_*, y_*, z_*) \in \cM \times \R^m \times \R^q_-$ such that
    \[ \lim_{K \ni k \to \infty} \left ( d(x_k, x_*) + \norm{y_k - y_*}_2 + \norm{z_k - z_*}_2 \right ) = 0. \]
    If the CPLD condition holds at $x_*$, then there exist $K_0 \subseteq K$ and $\lambda_* \in \R^m, \gamma_* \in \R^q_+$ such that $\lim_{K_0 \ni k \to \infty} \lambda_{k+1} = \lambda_*$, and the KKT conditions \eqref{eqn:reformulated-kkt} hold at $(x_*, y_*, z_*, \lambda_*, \gamma_*)$. Moreover, when the LICQ holds at $x_*$, we can choose $\gamma_*$ such that $\lim_{K_0 \ni k \to \infty} \gamma_{k + 1} = \gamma_*$.
\end{theorem}

