proof.raw_tex:
\begin{proposition}[Theorem 4.1.4 in \cite{hiriart1993convex}]
	\label{prop:moreau-yosida}
	Let $\sigma > 0$ and $f: \R^n \to \R \cup \{ +\infty \}$ be a closed proper convex function, then the Moreau-Yosida regularization $f^\sigma$ is continuously differentiable, and its gradient is 
	\begin{equation}
		\label{eqn:moreau-yosida-gradient}
		\nabla f^\sigma(x) = \frac{1}{\sigma}(x - \prox_{f/\sigma}(x)),
	\end{equation}
	where $\prox_{f / \sigma}$ is the \emph{proximal map} of the function $f / \sigma$:
	 \begin{equation}
		\prox_{f / \sigma} (x) := \argmin_{y} \left \{ f(y) + \frac{\sigma}{2}\norm{x-y}_2^2 \right \}.
	\end{equation}
\end{proposition}

\begin{theorem}
	\label{thm:feasibility}
	Let $\{ (x_k, y_k, z_k) \}$ be the sequence generated by Algorithm~\ref{alg:alm-outer}.
	Then, we have
	\[ \lim_{k\to \infty} \left( \norm{h_1(x_k) - y_k}_2 + \norm{h_2(x_k) - z_k}_2 \right) = 0. \]
	Consequently, if $x_* \in \cM$ is an accumulation point of $\{ x_k \}$, then $(x_*, h_1(x_*), h_2(x_*))$ is a feasible accumulation point of $\left\{ (x_k, y_k, z_k) \right\}$. %
	Moreover, $\{ x_k \}$ always contains an accumulation point if $\cM$ is compact.
\end{theorem}

\begin{proof}
    First, consider the case where $\{ \sigma_k \}$ is bounded. There exists $k_1 \in \N$ such that $\delta_{k+1} \leq \tau \delta_k$ for any $k \geq k_1$.
    Then, $\lim_{k \to \infty} \delta_k = 0$ since $\tau < 1$. 
    By the definition of $\delta_k$, we know $\lim_{k \to \infty} \norm{h_1(x_k) - y_k}_2 = 0$ and $\lim_{k\to \infty} \norm{h_2(x_k) - z_k}_2 = 0$. 

	In the case where $\{ \sigma_k \}$ is unbounded. By the update rule, $\sigma_k$ is updated for infinitely many times. Then, we can find $k_1 < k_2 < \cdots$ such that
	\[ \begin{aligned}
			\sigma_k = \sigma_{k_i} &= \max\big\{ \rho \sigma_{k_{i-1}}, \norm{\lambda_{k_i}}_2^{1 + \alpha}, \norm{\gamma_{k_i}}_2^{1 + \alpha} \big\},\ \forall \, k_i \leq k < k_{i+1}.
	\end{aligned} \]


