			&\leq \frac{\norm{\lambda_{k_i}}_2}{\sigma_{k_i}} + \sum_{j=k_i}^{k-1} \delta_j
			\leq \frac{\norm{\lambda_{k_i}}_2}{\sigma_{k_i}} + \delta_{k_i} \sum_{j=0}^{k - k_i -1} \tau^{j}
			\leq \frac{\norm{\lambda_{k_i}}_2}{\sigma_{k_i}} + \frac{\delta_{k_i}}{1 - \tau}.
	\end{aligned} \]

