\begin{theorem}
    \label{thm:kkt}
    Suppose there exist $K \subseteq \N$ and $(x_*, y_*, z_*) \in \cM \times \R^m \times \R^q_-$ such that
    \[ \lim_{K \ni k \to \infty} \left ( d(x_k, x_*) + \norm{y_k - y_*}_2 + \norm{z_k - z_*}_2 \right ) = 0. \]
    If the CPLD condition holds at $x_*$, then there exist $K_0 \subseteq K$ and $\lambda_* \in \R^m, \gamma_* \in \R^q_+$ such that $\lim_{K_0 \ni k \to \infty} \lambda_{k+1} = \lambda_*$, and the KKT conditions \eqref{eqn:reformulated-kkt} hold at $(x_*, y_*, z_*, \lambda_*, \gamma_*)$. Moreover, when the LICQ holds at $x_*$, we can choose $\gamma_*$ such that $\lim_{K_0 \ni k \to \infty} \gamma_{k + 1} = \gamma_*$.
\end{theorem}

\begin{proof}
    First, from Theorem~\ref{thm:feasibility}, we obtain the feasibility condition \eqref{eqn:reformulated-kkt-feas}.
    From \eqref{eqn:subproblem-y}, \eqref{eqn:subproblem-z} and the property of Moreau-Yosida regularizations in Proposition~\ref{prop:moreau-yosida}, we know that
    \[ \begin{aligned} 
        y_k %
        = h_1(x_k) +  \frac{\lambda_k}{\sigma_k} - \frac{1}{\sigma_k} \nabla \psi^{\sigma_k}\left (h_1(x_k) +  \frac{\lambda_k}{\sigma_k}\right), \text{ and }
        z_k %
        = h_2(x_k) +  \frac{\gamma_k}{\sigma_k} - \frac{1}{\sigma_k} \nabla \delta_{\R_-^q}^{\sigma_k}\left (h_2(x_k) +  \frac{\gamma_k }{ \sigma_k}\right). 
	\end{aligned} \]
    From the definition of $\lambda_{k+1}$ and $\gamma_{k+1}$, combining the above two equations, we have
	\begin{equation}
		\label{eqn:grad_Lk}
		\begin{aligned}
			& \grad L_k(x_k)
			= \grad f(x_k) + \sum_{i=1}^m [\lambda_{k+1}]_i \grad\,[h_1(x_k)]_i 
			+ \sum_{i=1}^q [\gamma_{k+1}]_i \grad\, [h_2(x_k)]_i,  
		\end{aligned}
	\end{equation}
	where the chain rule for gradients on manifolds is used\footnote{
	Let $g: \cM \to \R^m$ and $f: \R^m \to \R$ be two smooth maps,
	we can use Definition~\ref{def:riemannian-gradient} to compute the gradient of $f \circ g$.
	For $p \in \cM$, $\xi_p \in T_p\cM$, choosing any curve $\gamma: (-1, 1) \to \cM$ such that $\gamma(0) = p$ and $\dot \gamma(0) = \xi_p$, we have
	$\inner{\xi_p}{\grad\,(f\circ g)(p)} = \xi_p (f \circ g) 
	= \left.\frac{\dd (f \circ g \circ \gamma)(t)}{\dd t}\right|_{t=0} 
	= \sum_{i=1}^m\alpha_i\left.\frac{\dd (g_i \circ \gamma)(t)}{\dd t}\right|_{t=0} 
	= \sum_{i=1}^m \alpha_i \cdot (\xi_p g_i) 
	= \sum_{i=1}^m \alpha_i \inner{\xi_p}{\grad\,[g(p)]_i}$, where $\alpha := \nabla f(q)$, $q := g(\gamma(t))$ and $g_i$ is the $i$-th component of $g$.
	Thus, $\grad\, (f \circ g)(p) = \sum_{i=1}^m \alpha_i \grad\, [g(p)]_i$.
	}.

    Since $y_k = \prox_{\psi/\sigma_k} (h_1(x_k) +  \lambda_k/\sigma_k)$, then
	\begin{equation}
		\label{eqn:grad_yk}
		0 \in \partial \psi(y_k) - (\sigma_k(h_1(x_k) - y_k) +  \lambda_k) = \partial \psi(y_k) - \lambda_{k+1}. 
	\end{equation}
	Note that $\lim_{K \ni k \to \infty} y_k = y_*$, then $\left\{ y_k \right\}_{k\in K}$ is bounded.
	By the locally boundedness of the subdifferential~\cite[Corollary 24.5.1]{rockafellar1970convex}, $\bigcup_{k \in K} \partial \psi(y_k)$ is also bounded.
	Therefore, $\{ \lambda_{k+1} \}_{k \in K}$ is bounded, so we can choose $K_1 \subseteq K$, $\lambda_* \in \R^m$ such that $\lim_{ K_1 \ni k \to \infty} \lambda_{k+1} = \lambda_*$, which implies $\lambda_*\in\partial\psi(y_*)$.

	On the other hand, since 
	\[ z_k = \Pi_{\R_-^q} \left ( h_2(x_k) +  \frac{\gamma_k}{\sigma_k} \right ) = \argmin_{z \leq 0} \norm{h_2(x_k) +  \frac{\gamma_k}{\sigma_k} - z}^2_2, \]
then from the optimality condition of the above problem, it holds that
	\begin{equation}
		\label{eqn:grad_zk}
		0 = [\sigma_k( h_2(x_k) - z_k) +  \gamma_k]^\trans z_k = \gamma_{k+1}^\trans z_k \quad \mathrm{and} \quad \gamma_{k+1} \geq 0.
	\end{equation}



	Let $\cA_{k} = \{ i \in [q] : [z_k]_i = 0 \}$, from \eqref{eqn:grad_zk}, we know $[\gamma_{k+1}]_i = 0$ for $i \notin \cA_k$. 
	Define $\cA_* := \{ i \in [q] : [z_*]_i = 0 \}$.
	Since $z_k \to z_*$, we also find that for sufficiently large $k$ and $i \notin \cA_*$, $[\gamma_{k+1}]_i = 0$.
	Then, when $k$ is large enough \eqref{eqn:grad_Lk} can be written as 
	\begin{equation}
		\label{eqn:alm-Astar-equ}
			\grad L_k(x_k)
			= \grad f(x_k) + \sum_{i=1}^m [\lambda_{k+1}]_i \grad\,[h_1(x_k)]_i 
			+ \sum_{i \in \cA_*} [\gamma_{k+1}]_i \grad\, [h_2(x_k)]_i.  
    \end{equation}
	Using the Carath\'eodory's theorem of cones~\cite{bertsekas1997nonlinear}, there exist $J_k \subseteq \cA_*$ and $[\hat \gamma_k]_j \geq 0$, where $j \in J_k$, such that $\left\{ \grad\, [h_2(x_k)]_j : j \in J_k \right\}$ are linearly independent and
	\begin{equation}
		\label{eqn:alm-J_k-equ}
			\grad L_k(x_k)
			= \grad f(x_k) + \sum_{i=1}^m [\lambda_{k+1}]_i \grad\,[h_1(x_k)]_i 
			+ \sum_{j \in J_k} [\hat\gamma_{k}]_j \grad\, [h_2(x_k)]_j,
	\end{equation}
	Since $J_k \subseteq [q]$ is a finite set, we can choose $J_*$ and $K_2 \subseteq K_1$ such that $J_k = J_*$ for all $k \in K_2$ and $|K_2| = \infty$.
	Define $M_k = \max\left\{ [\hat\gamma_{k}]_i : i \in J_* \right\}$ for $k \in K_2$.
	When $\{ M_k \}_{k \in K_2}$ is bounded, then we can find $K_3 \subseteq K_2$ and $\gamma_* \in \R^p_+$ such that $[\gamma_*]_i = 0$ for $i \notin J_*$ and $\lim_{ K_3 \ni k \to \infty} [\hat \gamma_k]_i = [\gamma_*]_i$ for $i \in J_*$.
	Using the fact that $\norm{\grad L_k(x_k)} \to 0$, \eqref{eqn:grad_Lk} implies \eqref{eqn:reformulated-kkt-x}.
	Since $J_* \subseteq \cA_*$ and $[\gamma_*]_i = 0$ for $i \notin J_*$, then \eqref{eqn:reformulated-kkt-z} follows.

	When $\{ M_k \}_{k\in K_2}$ is unbounded, we can find $K_4 \subseteq K_2$ and $\hat \gamma \in \R_+^q$ such that $\lim_{ K_4 \ni k \to \infty} [\hat \gamma_k]_i / M_k = [\hat \gamma]_i$ for $i \in J_*$ and $[\hat \gamma]_i = 0$ otherwise. By the definition of $M_k$, we have $\hat\gamma\neq 0$ and $\|\hat\gamma\|_\infty = 1$.
	Dividing \eqref{eqn:alm-J_k-equ} by $M_k$, using the boundedness of $\grad L_k(x_k)$, $\grad f(x_k)$ and $\grad\, [h_1(x_k)]_i$, letting $k \in K_4 \to \infty$ and noticing that $\lambda_{k + 1} \to \lambda_*$, $x_k \to x_*$, we can get
	\[  \sum_{j\in J_*} [\hat \gamma]_j \grad\, [h_2(x_*)]_j = 0.  \]
	Due to $\normz{\hat \gamma}_\infty = 1$ and $\hat \gamma \geq 0$, we know $\left\{ \grad\, [h_2(x_*)]_j : j \in J_* \right\}$ are linearly dependent with non-negative coefficients. However, they are linearly independent near $x_*$, which contradicts to the CPLD assumption. Thus, $M_k$ is always bounded.
	Moreover, when the LICQ holds at $x_*$ but $\{ \gamma_{k + 1} \}$ is unbounded, we can divide \eqref{eqn:alm-Astar-equ} by $\norm{\gamma_{k + 1}}_2$ and yield a contradiction to the LICQ condition. Therefore, $\{ \gamma_{k+1} \}$ is bounded and contains a convergent subsequence.
\hfill $\Box$
\end{proof}

\begin{equation}
	\label{eqn:original-problem}
	\begin{aligned}
		\min_{x}\  &\{f(x) + \psi(h_1(x)) \}, \quad 
		\mathrm{s.t.}\  x \in \cM,\ h_2(x) \leq 0.
	\end{aligned}
\end{equation}

\begin{equation}
	\label{eqn:reformulated-problem}
	\begin{aligned}
		\min_{x, y, z}\  &\{f(x) + \psi(y) \}, \quad
		\mathrm{s.t.}\  x \in \cM, \
		 y = h_1(x), \
		 z = h_2(x),\ z \leq 0.
	\end{aligned}
\end{equation}

\begin{assumption}
	$\cM$ is a complete smooth Riemannian manifold.
\end{assumption}

\begin{assumption}
	$f : \cM \to \R$, $h_1: \cM \to \R^m$, $h_2: \cM \to \R^{q}$ are continuously differentiable, and~$\psi: \R^m \to \R$ is a convex function.
	$f(x) + \psi(y)$ is bounded below for $(x, y) \in \cM \times \R^m$.
\end{assumption}

\begin{definition} %
	Given $p,q\in\cM$, the \emph{distance between $p$ and $q$} is defined as 
	\begin{equation*}
	d(p,q) = \inf \left\{ \ell(\gamma)  :  \ell(\gamma) := \int_0^1 \sqrt{\inner{\dot \gamma(t)}{\dot\gamma(t)}} \dd t \right\},
	\end{equation*}
	where $\inf$ is taken over all piecewise smooth curves $\gamma:[0,1]\to\cM$  with $\gamma(0)=p$ and $\gamma(1)=q$.
\end{definition}

\begin{definition}
    Let $f: \cM \to \cN$ be a smooth map between smooth manifolds $\cM, \cN$, the \emph{differential of $f$ at $p\in\cM$}, denoted by $\dd f|_p$, is a map from $T_p\cM$ to $T_{f(p)}\cN$ such that $(\dd f|_p\eta) g:= \eta(g \circ f)$ for all $g \in \cD(\cN)$ and $\eta \in T_p\cM$.
\end{definition}

\begin{definition}%
	\label{def:riemannian-gradient}
	Let $f:\cM\to\R$ be a smooth function 
	and $p\in\cM$, the \emph{gradient} of $f$ at $p$ is defined as the unique tangent vector $\grad f(p)\in T_p\cM$ that satisfies 
		 $$\xi_p f = \inner{\xi_p}{\grad f(p)},\ \forall\xi_p \in T_p\cM.$$
\end{definition}

The augmented Lagrangian function $L_\sigma: \cM \times \R^m \times \R_-^q \times \R^m \times \R^q \to \R$ of \eqref{eqn:reformulated-problem} is given by
\begin{equation}
	\begin{aligned} 
\peq	L_\sigma(x, y, z, \lambda, \gamma)  
= f(x) + \psi(y) 
+ \frac{\sigma}{2} \norm{h_1(x) - y + \frac{\lambda}{\sigma}}^2_2 
+ \frac{\sigma}{2}\norm{h_2(x) - z + \frac{\gamma}{\sigma}}_2^2 
- \frac{\norm{\lambda}_2^2 + \norm{\gamma}_2^2}{2\sigma}.
	\end{aligned}
	\label{eqn:L_sigma}
\end{equation}

where $\psi^\sigma$, $\delta_{\R^q_-}^\sigma$ are the \emph{Moreau-Yosida regularization} of $\psi$, $\delta_{\R^q_-}$, respectively. 
More specifically, it holds that
\begin{align}
    \psi^\sigma(x) &:= \min_{y \in \R^m}  \left \{ \psi(y)  
    + \frac{\sigma}{2} \norm{x - y}^2_2 \right \}, \label{prob:y}\\
    \delta_{\R_-^q}^\sigma(x) &:= \min_{z \in \R^q} \left \{ \delta_{\R_-^q}(z) + \frac{\sigma}{2}\norm{x - z}_2^2 \right \}, \label{prob:z}
\end{align}

\begin{proposition}[Theorem 4.1.4 in \cite{hiriart1993convex}]
	\label{prop:moreau-yosida}
	Let $\sigma > 0$ and $f: \R^n \to \R \cup \{ +\infty \}$ be a closed proper convex function, then the Moreau-Yosida regularization $f^\sigma$ is continuously differentiable, and its gradient is 
	\begin{equation}
		\label{eqn:moreau-yosida-gradient}
		\nabla f^\sigma(x) = \frac{1}{\sigma}(x - \prox_{f/\sigma}(x)),
	\end{equation}
	where $\prox_{f / \sigma}$ is the \emph{proximal map} of the function $f / \sigma$:
	 \begin{equation}
		\prox_{f / \sigma} (x) := \argmin_{y} \left \{ f(y) + \frac{\sigma}{2}\norm{x-y}_2^2 \right \}.
	\end{equation}
\end{proposition}

\begin{alg}[An augmented Lagrangian method for solving \eqref{eqn:reformulated-problem}]
	\label{alg:alm-outer}
	Choose initial values $x_0 \in \cM$, $\gamma_0 \in \R^{q}_+$, $\lambda_0 \in \R^m$, $\sigma_0 > 0$, $\alpha, \tau \in (0, 1)$, $\rho > 1$ 
	and a sequence $\{ \varepsilon_k \} \subseteq \R_+$ converging to $0$.
	Let $y_0 = \prox_{\psi/\sigma_0} ( h_1(x_0) + \lambda_0 / \sigma_0)$, $z_0 = \Pi_{\R_-^q} ( h_2(x_0) + \gamma_0 / \sigma_0)$, where $\Pi_{\R_-^q}$ is the projection onto $\R_-^q$. %
	Choose a feasible point $x_\feas$ and a constant $\Phi$ such that
	\begin{equation}
		\label{eqn:initial-maximal}
		\Phi \geq \max\{  f(x_\feas) + \psi(h_1(x_\feas)),\ L_{\sigma_0}(x_0, y_0, z_0, \lambda_0, \gamma_0)  \}.
	\end{equation}
	Our algorithm repeats the following steps for $k = 1, 2, \dots$

    \begin{enumerate}[label=(\roman*)]
	\item
	Find $x_k\in\cM$ such that
	\begin{equation}
		\label{eqn:subproblem-stopping-rule}
		\norm{\grad L_k (x_k)} < \varepsilon_k, \quad L_k(x_k) \leq \Phi,
	\end{equation}
	where 
	\begin{equation}
	L_k(x) := f(x) 
	+ \psi^{\sigma_k} \left ( h_1(x) + \frac{\lambda_k}{\sigma_k}  \right )
	+ \delta_{\R_-^q}^{\sigma_k} \left ( h_2(x) + \frac{\gamma_k}{\sigma_k}  \right ).
	\label{eqn:Lk}
	\end{equation}
	\item Update $y$ and $z$ using
    \begin{align}
        \label{eqn:subproblem-y}
        y_k &= \prox_{\psi/\sigma_k}\left ( h_1(x_k) + \frac{\lambda_k}{\sigma_k}  \right ),\\
        \label{eqn:subproblem-z}
        z_k &= \Pi_{\R_-^q} \left ( h_2(x_k) +  \frac{\gamma_k}{ \sigma_k} \right).
    \end{align}

	\item %
	Update the multipliers:
    \[ \begin{aligned}
        \lambda_{k+1} &= \lambda_k + \sigma_k (h_1(x_k) - y_k), \quad 
        \gamma_{k+1} = \gamma_k +\sigma_k (h_2(x_k) - z_k).
    \end{aligned} \]

	\item
	Let 
        $     \delta_k = \max\left\{ \norm{h_1(x_k) - y_k}_2,\ \norm{h_2(x_k)-z_k}_2\right\}.
        $ %

		 If $\delta_k \leq \tau \delta_{k-1}$, then $\sigma_{k+1} = \sigma_k$.
		 Otherwise, set
         \begin{equation}
            \label{eqn:alm-update-penalty}
			\sigma_{k+1} = \max \left \{ \rho\sigma_k,\ \norm{\lambda_{k+1}}_2^{1+\alpha},\ \norm{\gamma_{k+1}}_2^{1+\alpha} \right \}. 
		 \end{equation}
	\end{enumerate}
\end{alg}

\begin{definition}[LICQ]
	\label{def:LICQ}
	We say that a feasible point $x \in \cM$ of \eqref{eqn:original-problem} satisfies the \emph{linear independence constraint qualification} (LICQ) if
    $\{ \grad\, [h_2(x)]_i : i \in \cA(x) \}$ are linearly independent in $T_x\cM$.
\end{definition}

    \begin{subequations}
        \label{eqn:reformulated-kkt}
        \begin{align}
			 y = h_1(x),\ z = h_2(x), \label{eqn:reformulated-kkt-feas} \\
			 z \in \R^q_-,\ 
            \gamma \in \R^q_+,\ \gamma^\trans z = 0, \label{eqn:reformulated-kkt-z} \\
            0 \in \partial_y \tilde \cL(x, y, z, \lambda, \gamma), \label{eqn:reformulated-kkt-y} \\
            \mathrm{grad}_x\, \tilde \cL(x, y, z, \lambda, \gamma) = 0. \label{eqn:reformulated-kkt-x}
        \end{align}
	\end{subequations}

\begin{theorem}
	\label{thm:feasibility}
	Let $\{ (x_k, y_k, z_k) \}$ be the sequence generated by Algorithm~\ref{alg:alm-outer}.
	Then, we have
	\[ \lim_{k\to \infty} \left( \norm{h_1(x_k) - y_k}_2 + \norm{h_2(x_k) - z_k}_2 \right) = 0. \]
	Consequently, if $x_* \in \cM$ is an accumulation point of $\{ x_k \}$, then $(x_*, h_1(x_*), h_2(x_*))$ is a feasible accumulation point of $\left\{ (x_k, y_k, z_k) \right\}$. %
	Moreover, $\{ x_k \}$ always contains an accumulation point if $\cM$ is compact.
\end{theorem}

\begin{proof}
    First, consider the case where $\{ \sigma_k \}$ is bounded. There exists $k_1 \in \N$ such that $\delta_{k+1} \leq \tau \delta_k$ for any $k \geq k_1$.
    Then, $\lim_{k \to \infty} \delta_k = 0$ since $\tau < 1$. 
    By the definition of $\delta_k$, we know $\lim_{k \to \infty} \norm{h_1(x_k) - y_k}_2 = 0$ and $\lim_{k\to \infty} \norm{h_2(x_k) - z_k}_2 = 0$. 

	In the case where $\{ \sigma_k \}$ is unbounded. By the update rule, $\sigma_k$ is updated for infinitely many times. Then, we can find $k_1 < k_2 < \cdots$ such that
	\[ \begin{aligned}
			\sigma_k = \sigma_{k_i} &= \max\big\{ \rho \sigma_{k_{i-1}}, \norm{\lambda_{k_i}}_2^{1 + \alpha}, \norm{\gamma_{k_i}}_2^{1 + \alpha} \big\},\ \forall \, k_i \leq k < k_{i+1}.
	\end{aligned} \]


	From \eqref{eqn:subproblem-stopping-rule} and the definition of $L_k(x)$, we know that $L_{\sigma_{k}}(x_{k}, y_{k}, z_{k}, \lambda_{k}, \gamma_{k}) \leq \Phi$, where $L_{\sigma_k}$ is defined in \eqref{eqn:L_sigma}. Therefore, we have
	\begin{equation}
		\norm{h_1(x_{k}) - y_{k} + \frac{\lambda_{k}}{\sigma_{k}}}^2_2 
		+ \norm{h_2(x_{k}) - z_{k} + \frac{\gamma_{k}}{\sigma_{k}}}_2^2 
		\leq 2\frac{ \Phi - f(x_{k}) - \psi(y_{k}) }{\sigma_{k}} 
		+ \frac{\norm{\lambda_{k}}_2^2 + \norm{\gamma_{k}}_2^2}{\sigma_{k}^2}.
		\label{eqn:feasibility-bounded}
	\end{equation}

	Since $f + \psi$ is bounded below and $\sigma_{k} \to \infty$, then the first term of \eqref{eqn:feasibility-bounded} converges to $0$. Next, we show that the second term also converges to $0$.
	Notice that $\norm{\lambda_{k_i}}_2^{1+\alpha} \leq \sigma_{k_i}$ and $\sigma_{k_i} \to \infty$, 
	we have $\norm{\lambda_{k_i}}_2 / \sigma_{k_i} \leq \sigma_{k_i}^{-\frac{\alpha}{1 + \alpha}} \to 0$ as $i \to \infty$. A similar result also holds for $\norm{\gamma_{k_i}}_2 / \sigma_{k_i}$. 
	Then by \eqref{eqn:feasibility-bounded} and the definition of $\delta_{k_i}$, we have $\lim_{i \to \infty} \delta_{k_i} = 0$.
	By the update rule of $\lambda_k$, for $k_i < k < k_{i+1}$, it holds that 
	\[\begin{aligned}
			\frac{\norm{\lambda_{k}}_2}{\sigma_{k}} 
			&\leq \frac{\norm{\lambda_{k - 1}}_2}{\sigma_{k_i}} + \norm{h_1(x_{k - 1}) - y_{k - 1}}_2 
			\leq \frac{\norm{\lambda_{k - 1}}_2}{\sigma_{k_i}} + \delta_{k-1}.
	\end{aligned} \]

	Also note that $\delta_k \leq \tau\delta_{k-1}$ for all $k_i \leq k < k_{i+1} - 1$. Then, for $k_i < k < k_{i+1}$ the following inequality holds by induction
	\[\begin{aligned}
			\frac{\norm{\lambda_{k}}_2}{\sigma_{k}} 
			&\leq \frac{\norm{\lambda_{k_i}}_2}{\sigma_{k_i}} + \sum_{j=k_i}^{k-1} \delta_j
			\leq \frac{\norm{\lambda_{k_i}}_2}{\sigma_{k_i}} + \delta_{k_i} \sum_{j=0}^{k - k_i -1} \tau^{j}
			\leq \frac{\norm{\lambda_{k_i}}_2}{\sigma_{k_i}} + \frac{\delta_{k_i}}{1 - \tau}.
	\end{aligned} \]

	Thus, we have $\lim_{k \to \infty} \norm{\lambda_k}_2 / \sigma_k = 0$.
	Similarly, $\lim_{k \to \infty} \norm{\gamma_k}_2 / \sigma_k = 0$. Therefore, from \eqref{eqn:feasibility-bounded}, we conclude that $\lim_{k \to \infty} \delta_k = 0$. \hfill $\Box$
\end{proof}

From \eqref{eqn:subproblem-stopping-rule} and the definition of $L_k(x)$, we know that $L_{\sigma_{k}}(x_{k}, y_{k}, z_{k}, \lambda_{k}, \gamma_{k}) \leq \Phi$, where $L_{\sigma_k}$ is defined in \eqref{eqn:L_sigma}. Therefore, we have
\begin{equation}
	\norm{h_1(x_{k}) - y_{k} + \frac{\lambda_{k}}{\sigma_{k}}}^2_2 
	+ \norm{h_2(x_{k}) - z_{k} + \frac{\gamma_{k}}{\sigma_{k}}}_2^2 
	\leq 2\frac{ \Phi - f(x_{k}) - \psi(y_{k}) }{\sigma_{k}} 
	+ \frac{\norm{\lambda_{k}}_2^2 + \norm{\gamma_{k}}_2^2}{\sigma_{k}^2}.
	\label{eqn:feasibility-bounded}
\end{equation}

By the update rule of $\lambda_k$, for $k_i < k < k_{i+1}$, it holds that 
\[\begin{aligned}
		\frac{\norm{\lambda_{k}}_2}{\sigma_{k}} 
		&\leq \frac{\norm{\lambda_{k - 1}}_2}{\sigma_{k_i}} + \norm{h_1(x_{k - 1}) - y_{k - 1}}_2 
		\leq \frac{\norm{\lambda_{k - 1}}_2}{\sigma_{k_i}} + \delta_{k-1}.
\end{aligned} \]

Also note that $\delta_k \leq \tau\delta_{k-1}$ for all $k_i \leq k < k_{i+1} - 1$. Then, for $k_i < k < k_{i+1}$ the following inequality holds by induction
\[\begin{aligned}
		\frac{\norm{\lambda_{k}}_2}{\sigma_{k}} 
		&\leq \frac{\norm{\lambda_{k_i}}_2}{\sigma_{k_i}} + \sum_{j=k_i}^{k-1} \delta_j
		\leq \frac{\norm{\lambda_{k_i}}_2}{\sigma_{k_i}} + \delta_{k_i} \sum_{j=0}^{k - k_i -1} \tau^{j}
		\leq \frac{\norm{\lambda_{k_i}}_2}{\sigma_{k_i}} + \frac{\delta_{k_i}}{1 - \tau}.
\end{aligned} \]

	Thus, we have $\lim_{k \to \infty} \norm{\lambda_k}_2 / \sigma_k = 0$.
	Similarly, $\lim_{k \to \infty} \norm{\gamma_k}_2 / \sigma_k = 0$. Therefore, from \eqref{eqn:feasibility-bounded}, we conclude that $\lim_{k \to \infty} \delta_k = 0$. \hfill $\Box$
\end{proof}

    From the definition of $\lambda_{k+1}$ and $\gamma_{k+1}$, combining the above two equations, we have
	\begin{equation}
		\label{eqn:grad_Lk}
		\begin{aligned}
			& \grad L_k(x_k)
			= \grad f(x_k) + \sum_{i=1}^m [\lambda_{k+1}]_i \grad\,[h_1(x_k)]_i 
			+ \sum_{i=1}^q [\gamma_{k+1}]_i \grad\, [h_2(x_k)]_i,  
		\end{aligned}
	\end{equation}

where the chain rule for gradients on manifolds is used\footnote{
Let $g: \cM \to \R^m$ and $f: \R^m \to \R$ be two smooth maps,
we can use Definition~\ref{def:riemannian-gradient} to compute the gradient of $f \circ g$.
For $p \in \cM$, $\xi_p \in T_p\cM$, choosing any curve $\gamma: (-1, 1) \to \cM$ such that $\gamma(0) = p$ and $\dot \gamma(0) = \xi_p$, we have
$\inner{\xi_p}{\grad\,(f\circ g)(p)} = \xi_p (f \circ g) 
= \left.\frac{\dd (f \circ g \circ \gamma)(t)}{\dd t}\right|_{t=0} 
= \sum_{i=1}^m\alpha_i\left.\frac{\dd (g_i \circ \gamma)(t)}{\dd t}\right|_{t=0} 
= \sum_{i=1}^m \alpha_i \cdot (\xi_p g_i) 
= \sum_{i=1}^m \alpha_i \inner{\xi_p}{\grad\,[g(p)]_i}$, where $\alpha := \nabla f(q)$, $q := g(\gamma(t))$ and $g_i$ is the $i$-th component of $g$.
Thus, $\grad\, (f \circ g)(p) = \sum_{i=1}^m \alpha_i \grad\, [g(p)]_i$.
}.

    Since $y_k = \prox_{\psi/\sigma_k} (h_1(x_k) +  \lambda_k/\sigma_k)$, then
	\begin{equation}
		\label{eqn:grad_yk}
		0 \in \partial \psi(y_k) - (\sigma_k(h_1(x_k) - y_k) +  \lambda_k) = \partial \psi(y_k) - \lambda_{k+1}. 
	\end{equation}
	Note that $\lim_{K \ni k \to \infty} y_k = y_*$, then $\left\{ y_k \right\}_{k\in K}$ is bounded.
	By the locally boundedness of the subdifferential~\cite[Corollary 24.5.1]{rockafellar1970convex}, $\bigcup_{k \in K} \partial \psi(y_k)$ is also bounded.
	Therefore, $\{ \lambda_{k+1} \}_{k \in K}$ is bounded, so we can choose $K_1 \subseteq K$, $\lambda_* \in \R^m$ such that $\lim_{ K_1 \ni k \to \infty} \lambda_{k+1} = \lambda_*$, which implies $\lambda_*\in\partial\psi(y_*)$.

	On the other hand, since 
	\[ z_k = \Pi_{\R_-^q} \left ( h_2(x_k) +  \frac{\gamma_k}{\sigma_k} \right ) = \argmin_{z \leq 0} \norm{h_2(x_k) +  \frac{\gamma_k}{\sigma_k} - z}^2_2, \]
then from the optimality condition of the above problem, it holds that
	\begin{equation}
		\label{eqn:grad_zk}
		0 = [\sigma_k( h_2(x_k) - z_k) +  \gamma_k]^\trans z_k = \gamma_{k+1}^\trans z_k \quad \mathrm{and} \quad \gamma_{k+1} \geq 0.
	\end{equation}

	Let $\cA_{k} = \{ i \in [q] : [z_k]_i = 0 \}$, from \eqref{eqn:grad_zk}, we know $[\gamma_{k+1}]_i = 0$ for $i \notin \cA_k$. 
	Define $\cA_* := \{ i \in [q] : [z_*]_i = 0 \}$.
	Since $z_k \to z_*$, we also find that for sufficiently large $k$ and $i \notin \cA_*$, $[\gamma_{k+1}]_i = 0$.
	Then, when $k$ is large enough \eqref{eqn:grad_Lk} can be written as 
	\begin{equation}
		\label{eqn:alm-Astar-equ}
			\grad L_k(x_k)
			= \grad f(x_k) + \sum_{i=1}^m [\lambda_{k+1}]_i \grad\,[h_1(x_k)]_i 
			+ \sum_{i \in \cA_*} [\gamma_{k+1}]_i \grad\, [h_2(x_k)]_i.  
    \end{equation}

Using the Carath\'eodory's theorem of cones~\cite{bertsekas1997nonlinear}, there exist $J_k \subseteq \cA_*$ and $[\hat \gamma_k]_j \geq 0$, where $j \in J_k$, such that $\left\{ \grad\, [h_2(x_k)]_j : j \in J_k \right\}$ are linearly independent and
\begin{equation}
	\label{eqn:alm-J_k-equ}
		\grad L_k(x_k)
		= \grad f(x_k) + \sum_{i=1}^m [\lambda_{k+1}]_i \grad\,[h_1(x_k)]_i 
		+ \sum_{j \in J_k} [\hat\gamma_{k}]_j \grad\, [h_2(x_k)]_j,
\end{equation}
Since $J_k \subseteq [q]$ is a finite set, we can choose $J_*$ and $K_2 \subseteq K_1$ such that $J_k = J_*$ for all $k \in K_2$ and $|K_2| = \infty$.
Define $M_k = \max\left\{ [\hat\gamma_{k}]_i : i \in J_* \right\}$ for $k \in K_2$.

	Moreover, when the LICQ holds at $x_*$ but $\{ \gamma_{k + 1} \}$ is unbounded, we can divide \eqref{eqn:alm-Astar-equ} by $\norm{\gamma_{k + 1}}_2$ and yield a contradiction to the LICQ condition. Therefore, $\{ \gamma_{k+1} \}$ is bounded and contains a convergent subsequence.
\hfill $\Box$
\end{proof}
